1	// Real CompanyProvider backed by the Crustdata HTTP API. Mirrors the
2	// FixtureProvider's semantics: BudgetGuard is checked before every paid call,
3	// spend is recorded after success, enrich results are partial, and a call with
4	// no results is no_match. Providers return errors; they do not throw.
5	//
6	// Error messages are deliberately generic (status code and category only).
7	// They never contain the response body, the URL list or any header.
8	
9	import type { RawCompany, RawLocation } from "../types";
10	import {
11	  type BudgetGuard,
12	  type CompanyProvider,
13	  type ProviderErrorCategory,
14	  type ProviderResult,
15	  type SearchFilters,
16	} from "./provider";
17	
18	// Measured on our account (Oct 10-11, 2026, five measurements). Unmatched
19	// enrichments are assumed free (unverified).
20	export const CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD = 0.069;
21	export const CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD = 0.6;
22	
23	const API_VERSION = "2025-11-01";
24	const ENRICH_CHUNK_SIZE = 25;
25	const MAX_RETRY_AFTER_MS = 60_000;
26	
27	const SEARCH_FIELDS = [
28	  "crustdata_company_id",
29	  "basic_info.logo_permalink",
30	  "basic_info.name",
31	  "basic_info.primary_domain",
32	  "basic_info.website",
33	  "basic_info.professional_network_url",
34	  "basic_info.employee_count_range",
35	  "taxonomy.professional_network_industry",
36	];
37	
38	const ENRICH_FIELD_GROUPS = ["basic_info", "headcount", "locations", "taxonomy"];
39	
40	export interface CrustdataProviderOptions {
41	  readonly api_key: string;
42	  readonly budget: BudgetGuard;
43	  // Default https://api.crustdata.com
44	  readonly base_url?: string;
45	  // Default global fetch.
46	  readonly fetch?: typeof fetch;
47	  // Per-attempt timeout. Default 30000.
48	  readonly timeout_ms?: number;
49	  // Retries after the first attempt for 429 / 5xx / network errors. Default 2.
50	  readonly max_retries?: number;
51	  // Wait function used between retries. Default setTimeout. Mainly for tests.
52	  readonly sleep?: (ms: number) => Promise<void>;
53	  // Optional sort for searches. Default null, which omits "sorts" from the
54	  // request body. Live tests showed that sorting by basic_info.name ascending
55	  // returns the sparsest records first (empty name, domain, website and
56	  // LinkedIn URL), while an unsorted search returns complete records.
57	  readonly search_sort?: { readonly field: string; readonly order: "asc" | "desc" } | null;
58	}
59	
60	type Failure = { readonly ok: false; readonly error: { readonly category: ProviderErrorCategory; readonly message: string } };
61	type Json = unknown;
62	
63	export class CrustdataProvider implements CompanyProvider {
64	  readonly budget: BudgetGuard;
65	  private readonly api_key: string;
66	  private readonly base_url: string;
67	  private readonly fetch_fn: typeof fetch;
68	  private readonly timeout_ms: number;
69	  private readonly max_retries: number;
70	  private readonly sleep: (ms: number) => Promise<void>;
71	  private readonly search_sort: { readonly field: string; readonly order: "asc" | "desc" } | null;
72	
73	  constructor(options: CrustdataProviderOptions) {
74	    this.api_key = options.api_key;
75	    this.budget = options.budget;
76	    this.base_url = (options.base_url ?? "https://api.crustdata.com").replace(/\/+$/, "");
77	    this.fetch_fn = options.fetch ?? ((input, init) => fetch(input, init));
78	    this.timeout_ms = options.timeout_ms ?? 30_000;
79	    this.max_retries = options.max_retries ?? 2;
80	    this.sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
81	    this.search_sort = options.search_sort ?? null;
82	  }
83	
84	  async autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>> {
85	    const res = await this.post("/company/search/autocomplete", {
86	      field: "taxonomy.professional_network_industry",
87	      query,
88	      limit: 10,
89	    });
90	    if (!res.ok) return res;
91	    const raw = asRecord(res.json)?.suggestions;
92	    const values = (Array.isArray(raw) ? raw : [])
93	      .map((s) => str(asRecord(s)?.value))
94	      .filter((v) => v !== "");
95	    if (values.length === 0) return fail("no_match", "no industry suggestions");
96	    // Autocomplete is free and outside the search/enrich caps.
97	    return { ok: true, data: values, cost_usd: 0, calls: res.calls };
98	  }
99	
100	  async searchCompanies(
101	    filters: SearchFilters,
102	    limit: number,
103	  ): Promise<ProviderResult<readonly RawCompany[]>> {
104	    if (!this.budget.canSearch(limit)) {
105	      return fail("budget_cap_reached", "search cap would be exceeded");
106	    }
107	    const conditions: Record<string, unknown>[] = [];
108	    if (filters.country !== "") {
109	      conditions.push({ field: "locations.country", type: "=", value: filters.country });
110	    }
111	    if (filters.industries.length > 0) {
112	      conditions.push({
113	        field: "taxonomy.professional_network_industry",
114	        type: "in",
115	        value: filters.industries,
116	      });
117	    }
118	    if (filters.employee_count_ranges.length > 0) {
119	      conditions.push({
120	        field: "basic_info.employee_count_range",
121	        type: "in",
122	        value: filters.employee_count_ranges,
123	      });
124	    }
125	    const body: Record<string, unknown> = {
126	      fields: SEARCH_FIELDS,
127	      limit,
128	    };
129	    if (this.search_sort !== null) {
130	      body.sorts = [{ field: this.search_sort.field, order: this.search_sort.order }];
131	    }
132	    if (conditions.length > 0) body.filters = { op: "and", conditions };
133	
134	    const res = await this.post("/company/search", body);
135	    if (!res.ok) return res;
136	    const now = new Date().toISOString();
137	    const found = extractList(res.json)
138	      .slice(0, Math.max(limit, 0))
139	      .map((item) => mapSearchItem(item, now));
140	    if (found.length === 0) return fail("no_match", "no companies match the filters");
141	    const total = CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD * found.length;
142	    const data = found.map((c): RawCompany => ({ ...c, cost_usd: CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD }));
143	    this.budget.recordSearch(found.length, total);
144	    return { ok: true, data, cost_usd: total, calls: res.calls };
145	  }
146	
147	  async enrichCompanies(
148	    linkedin_urls: readonly string[],
149	  ): Promise<ProviderResult<readonly RawCompany[]>> {
150	    if (!this.budget.canEnrich(linkedin_urls.length)) {
151	      return fail("budget_cap_reached", "enrichment cap would be exceeded");
152	    }
153	    const matched: RawCompany[] = [];
154	    let cost = 0;
155	    let calls = 0;
156	    let first_failure: Failure | undefined;
157	
158	    for (let i = 0; i < linkedin_urls.length; i += ENRICH_CHUNK_SIZE) {
159	      const chunk = linkedin_urls.slice(i, i + ENRICH_CHUNK_SIZE);
160	      if (!this.budget.canEnrich(chunk.length)) {
161	        first_failure ??= fail("budget_cap_reached", "enrichment cap would be exceeded");
162	        break;
163	      }
164	      const res = await this.post("/company/enrich", {
165	        fields: ENRICH_FIELD_GROUPS,
166	        professional_network_profile_urls: chunk,
167	      });
168	      calls += res.calls;
169	      if (!res.ok) {
170	        first_failure ??= res;
171	        break;
172	      }
173	      const now = new Date().toISOString();
174	      const records = (Array.isArray(res.json) ? res.json : [])
175	        .map((element) => mapEnrichElement(element, now))
176	        .filter((c): c is RawCompany => c !== undefined);
177	      const chunk_cost = CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD * records.length;
178	      this.budget.recordEnrich(records.length, chunk_cost);
179	      matched.push(...records);
180	      cost += chunk_cost;
181	    }
182	
183	    // Partial results win over a later chunk's failure, like a partial match.
184	    if (matched.length > 0) return { ok: true, data: matched, cost_usd: cost, calls };
185	    return first_failure ?? fail("no_match", "no companies matched the LinkedIn URLs");
186	  }
187	
188	  // One POST with retries on 429, 5xx and network errors.
189	  private async post(
190	    path: string,
191	    body: unknown,
192	  ): Promise<{ ok: true; json: Json; calls: number } | (Failure & { calls: number })> {
193	    let calls = 0;
194	    for (let attempt = 0; ; attempt++) {
195	      calls += 1;
196	      const outcome = await this.attempt(path, body);
197	      if (outcome.kind === "ok") return { ok: true, json: outcome.json, calls };
198	      const failure = { ...fail(outcome.category, outcome.message), calls };
199	      if (!outcome.retryable || attempt >= this.max_retries) return failure;
200	      await this.sleep(outcome.retry_after_ms ?? 1000 * 2 ** attempt);
201	    }
202	  }
203	
204	  private async attempt(
205	    path: string,
206	    body: unknown,
207	  ): Promise<
208	    | { kind: "ok"; json: Json }
209	    | {
210	        kind: "error";
211	        category: ProviderErrorCategory;
212	        message: string;
213	        retryable: boolean;
214	        retry_after_ms?: number;
215	      }
216	  > {
217	    const controller = new AbortController();
218	    const timer = setTimeout(() => controller.abort(), this.timeout_ms);
219	    try {
220	      const response = await this.fetch_fn(`${this.base_url}${path}`, {
221	        method: "POST",
222	        headers: {
223	          "Content-Type": "application/json",
224	          Authorization: `Bearer ${this.api_key}`,
225	          "x-api-version": API_VERSION,
226	        },
227	        body: JSON.stringify(body),
228	        signal: controller.signal,
229	      });
230	      const status = response.status;
231	      if (status >= 200 && status < 300) {
232	        try {
233	          return { kind: "ok", json: await response.json() };
234	        } catch {
235	          return err("empty_or_partial", `HTTP ${status} unreadable response`, false);
236	        }
237	      }
238	      if (status === 401 || status === 403) return err("auth_failed", `HTTP ${status} auth_failed`, false);
239	      if (status === 429) {
240	        return {
241	          ...err("rate_limited", `HTTP ${status} rate_limited`, true),
242	          retry_after_ms: parseRetryAfter(response.headers?.get("retry-after") ?? null),
243	        };
244	      }
245	      if (status >= 500) return err("timeout", `HTTP ${status} timeout`, true);
246	      return err("bad_request", `HTTP ${status} bad_request`, false);
247	    } catch {
248	      return err("timeout", "request failed or timed out (timeout)", true);
249	    } finally {
250	      clearTimeout(timer);
251	    }
252	  }
253	}
254	
255	function err(category: ProviderErrorCategory, message: string, retryable: boolean) {
256	  return { kind: "error" as const, category, message, retryable };
257	}
258	
259	function fail(category: ProviderErrorCategory, message?: string): Failure {
260	  return { ok: false, error: { category, message: message ?? category } };
261	}
262	
263	function parseRetryAfter(value: string | null): number | undefined {
264	  if (value === null) return undefined;
265	  const seconds = Number(value);
266	  if (!Number.isFinite(seconds) || seconds < 0) return undefined;
267	  return Math.min(seconds * 1000, MAX_RETRY_AFTER_MS);
268	}
269	
270	// --- Mapping helpers: never throw on missing or null fields. ---------------
271	
272	function asRecord(v: unknown): Record<string, unknown> | undefined {
273	  return typeof v === "object" && v !== null && !Array.isArray(v)
274	    ? (v as Record<string, unknown>)
275	    : undefined;
276	}
277	
278	function str(v: unknown): string {
279	  return typeof v === "string" ? v : "";
280	}
281	
282	function num(v: unknown): number | undefined {
283	  return typeof v === "number" && Number.isFinite(v) ? v : undefined;
284	}
285	
286	// Reads "a.b" as nested a -> b.
287	function pick(obj: Record<string, unknown> | undefined, path: string): unknown {
288	  let cur: unknown = obj;
289	  for (const part of path.split(".")) cur = asRecord(cur)?.[part];
290	  return cur;
291	}
292	
293	// The search response is { companies: [...], next_cursor, total_count }.
294	function extractList(json: Json): unknown[] {
295	  const list = asRecord(json)?.companies;
296	  return Array.isArray(list) ? list : [];
297	}
298	
299	function mapSearchItem(item: unknown, retrieved_at: string): RawCompany {
300	  const o = asRecord(item);
301	  return {
302	    crustdata_company_id: num(pick(o, "crustdata_company_id")) ?? 0,
303	    name: str(pick(o, "basic_info.name")),
304	    primary_domain: str(pick(o, "basic_info.primary_domain")),
305	    website: str(pick(o, "basic_info.website")),
306	    professional_network_url: str(pick(o, "basic_info.professional_network_url")),
307	    employee_count_range: str(pick(o, "basic_info.employee_count_range")),
308	    industry: str(pick(o, "taxonomy.professional_network_industry")),
309	    logo: str(pick(o, "basic_info.logo_permalink")),
310	    source: "search",
311	    retrieved_at,
312	    cost_usd: 0,
313	  };
314	}
315	
316	// One element per input URL; takes the highest-confidence match, if any.
317	function mapEnrichElement(element: unknown, retrieved_at: string): RawCompany | undefined {
318	  const matches = asRecord(element)?.matches;
319	  if (!Array.isArray(matches)) return undefined;
320	  let best: Record<string, unknown> | undefined;
321	  let best_score = -Infinity;
322	  for (const m of matches) {
323	    const rec = asRecord(m);
324	    if (!rec || !asRecord(rec.company_data)) continue;
325	    const score = num(rec.confidence_score) ?? 0;
326	    if (score > best_score) {
327	      best = rec;
328	      best_score = score;
329	    }
330	  }
331	  const d = asRecord(best?.company_data);
332	  if (!d) return undefined;
333	
334	  const basic = asRecord(d.basic_info);
335	  const loc = asRecord(d.locations);
336	  const tax = asRecord(d.taxonomy);
337	
338	  // Only city / state / country are ever copied from locations.
339	  const location: { -readonly [K in keyof RawLocation]: RawLocation[K] } = {};
340	  if (str(loc?.city) !== "") location.city = str(loc?.city);
341	  if (str(loc?.state) !== "") location.state = str(loc?.state);
342	  if (str(loc?.country) !== "") location.country = str(loc?.country);
343	
344	  const founded = num(basic?.year_founded);
345	  const headcount = num(asRecord(d.headcount)?.total);
346	  const description = str(basic?.description);
347	  const legal_type = str(basic?.company_type);
348	  const specialities = Array.isArray(tax?.professional_network_specialities)
349	    ? (tax.professional_network_specialities as unknown[]).filter(
350	        (s): s is string => typeof s === "string" && s !== "",
351	      )
352	    : [];
353	
354	  return {
355	    crustdata_company_id: num(d.crustdata_company_id) ?? 0,
356	    name: str(basic?.name),
357	    primary_domain: str(basic?.primary_domain),
358	    website: str(basic?.website),
359	    professional_network_url: str(basic?.professional_network_url),
360	    employee_count_range: str(basic?.employee_count_range),
361	    industry: str(tax?.professional_network_industry),
362	    logo: str(basic?.logo_permalink),
363	    ...(description !== "" && { description }),
364	    ...(legal_type !== "" && { legal_type }),
365	    ...(founded !== undefined && { founded_year: founded }),
366	    ...(headcount !== undefined && { latest_headcount: headcount }),
367	    ...(Object.keys(location).length > 0 && { location }),
368	    ...(specialities.length > 0 && { specialities }),
369	    source: "enrich",
370	    retrieved_at,
371	    cost_usd: CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD,
372	  };
373	}
374

