  "crustdata_company_id",
  "basic_info.logo_permalink",
  "basic_info.name",
  "basic_info.primary_domain",
  "basic_info.website",
  "basic_info.professional_network_url",
  "basic_info.employee_count_range",
  "taxonomy.professional_network_industry",
